document.addEventListener('visibilitychange',()=>{if(document.hidden&&live)pause();});
$('export').onclick=()=>{if(!hasAnalyzed){toast('Сначала выполните анализ');return;}download('baywatch-report.json',{app:'BayWatch',version:'2.0.0',engine:analysisMode==='auto'?'COCO-SSD lite MobileNet v2':model.version,at:new Date().toISOString(),input:inputLabel,mode,analysisMode,width:source.width,height:source.height,inferenceMs:lastMs,vehicleThreshold:Number($('detThreshold').value)/100,tiled:$('detail').checked,frameQuality,detections,results,acknowledged:Array.from(ack),recentHistory:history,limitations:['Vehicle detection does not discover empty spaces','PKLot 99.27% metric applies only to zone classifier','No measured detector precision or recall on uploaded video','Scores and temporary IDs are not identity or safety guarantees']});};
function showEvidence(){const m=report.metrics.test;const cards=[['Точность на тесте',pct(m.accuracy),`${m.n} размеченных мест`],['F1 занятости',pct(m.f1),'Порог 0.5, без отказов'],['Покрытие при 20/80',pct(m.coverage_20_80),'Только по оценке модели'],['Точность принятых',pct(m.accepted_accuracy_20_80),'Без фильтра качества']];$('evalStats').replaceChildren();for(const[a,b,c]of cards){const el=document.createElement('article');const s=document.createElement('span'),v=document.createElement('strong'),n=document.createElement('small');s.textContent=a;v.textContent=b;n.textContent=c;el.append(s,v,n);$('evalStats').append(el);}let html='<table class="eval-table"><tr><th>Камера</th><th>Мест</th><th>Accuracy</th><th>F1</th></tr>';for(const [cam,m]of Object.entries(report.camera_metrics))html+=`<tr><td>${cam}</td><td>${m.n}</td><td>${pct(m.accuracy)}</td><td>${pct(m.f1)}</td></tr>`;html+='</table>';html+=`<p class="hint">Обучение: ${report.frames.train} кадров. Валидация: ${report.frames.valid}. Тест: ${report.frames.test}. Baseline «всегда самый частый класс»: ${pct(report.majority_baseline_test_accuracy)}. Seed 42; выбор эпохи и температуры — только по validation.</p>`;$('evalTable').innerHTML=html;}
$('evaluateDemo').onclick=()=>{if(demoIndex<0||!results.length||!zones.every(z=>Number.isInteger(z.truth))){$('demoEvaluation').textContent='Выберите PKLot-кадр, режим «Парковочные места» и выполните анализ.';return;}let correct=0,accepted=0;for(const r of results){if(r.state==='review')continue;accepted++;if(Number(r.state==='occupied')===zones.find(z=>z.id===r.id).truth)correct++;}$('demoEvaluation').textContent=`Принято ${accepted}/${results.length}; верно ${correct}/${accepted}${accepted?' ('+pct(correct/accepted)+')':''}. Учтены текущий порог и фильтр качества.`;};
async function stress(type){if(!original||live){toast('Проверка доступна для статического кадра');return;}setFrame(original);if(type==='dark'){sc.fillStyle='rgba(0,0,0,0.95)';sc.fillRect(0,0,source.width,source.height);}else{const small=document.createElement('canvas');small.width=16;small.height=9;small.getContext('2d').drawImage(source,0,0,16,9);sc.drawImage(small,0,0,source.width,source.height);}stabilizer.clear();ack.clear();await analyze();$('stressResult').textContent=analysisMode==='auto'?(frameQuality?.ok?'Кадр прошёл базовый фильтр; результат требует проверки.':'Модель воздержалась: '+(frameQuality?.reasons.join(', ')||'недостаточное качество')):`${type==='dark'?'Искусственная темнота':'Искусственное размытие'}: ${results.filter(r=>r.state==='review').length}/${results.length} зон требуют проверки.`;$('frameNote').textContent='Искусственная деградация исходного кадра. Не измерение реальной ночи или дождя.';}
$('stressDark').onclick=()=>stress('dark');$('stressBlur').onclick=()=>stress('blur');$('restore').onclick=async()=>{if(!original)return;setFrame(original);stabilizer.clear();ack.clear();await analyze();$('stressResult').textContent='Исходный кадр восстановлен.';$('frameNote').textContent='Исходный кадр. Ответы модели вычисляются по пикселям.';};
function calc(){const ids=['roiEvents','roiMinutes','roiHourly','roiCost','roiSetup'];const v=ids.map(id=>Math.max(0,Number($(id).value)||0));const r=roi({events:v[0],minutes:v[1],hourly:v[2],cost:v[3],setup:v[4]});$('roiResults').innerHTML=`<p class="roi-big">$${r.net.toFixed(0)} <small style="font-size:13px;font-weight:400">/ месяц, сценарный эффект</small></p><p class="hint">Время в денежном эквиваленте: $${r.saved.toFixed(0)}. Окупаемость: ${r.payback===null?'нет при этих условиях':r.payback.toFixed(1)+' мес.'} Это расчёт, не результат пилота.</p>`;}['roiEvents','roiMinutes','roiHourly','roiCost','roiSetup'].forEach(id=>$(id).oninput=calc);calc();
window.addEventListener('beforeunload',()=>{pause();if(stream)stream.getTracks().forEach(t=>t.stop());if(mediaUrl)URL.revokeObjectURL(mediaUrl);});
(async()=>{const initialGeneration=generation;try{[model,demos,report]=await Promise.all(['models/occupancy.json','data/demos.json','data/evaluation.json'].map(async p=>{const r=await fetch(p);if(!r.ok)throw Error('Не удалось загрузить '+p);return r.json();}));showEvidence();renderResults();if(generation===initialGeneration)await loadDemo('video');}catch(e){status('Ошибка загрузки',true);inputError(e.message);}})();
